    transition!{
        swing(key: Key, row: Row, col: Col, row2: Row, col2: Col) {
            require row < HEIGHT;
            require col < WIDTH;
            require row2 < HEIGHT;
            require col2 < WIDTH;
            require row == hash1(key) || row == hash2(key);
