}

fn compute_hash2(key: Key) -> (h: usize)
    ensures h == hash2(key) && h < HEIGHT
{
    let j = (key % 1048579u64) % ((HEIGHT - 1) as u64);
    (compute_hash1(key) + j as usize + 1) % HEIGHT
